-- =====================================================================
--  DEV ONLY: 20 test questions for the PG classes, in two published quizzes.
--  Paste the whole file into the SQL Editor of the DEV Supabase project
--  (never the real school one) and click Run. Run seed-dev.sql first.
--  Safe to run twice: the second run adds nothing.
--  Undo: remove-dev.sql removes these rows with the rest of the seed
--  (they all hang off the TEST PG-A / TEST PG-B classes).
--
--  Hand-written (not generated by `npm run seed:sql`). Uses only the question
--  types the student app answers today (features/attempts/QuestionCard.tsx):
--    tap_image   15  big emoji/letter tiles, sticker press motion, read-aloud
--                    speaker; prompt + labels in English and Urdu (db/006 shape)
--    true_false   2  stem holds English, then Urdu on the next line
--    mcq          2  same; options carry both languages
--    numeric      1  same
--  Stems of mcq/true_false/numeric are one string (the authoring shape,
--  core/questions.ts) so teachers can still edit them in the app.
--  Urdu is first-draft, written for this test set: a teacher should check it
--  (prompt C2) before anything like it reaches real students.
--
--  For each of TEST PG-A and TEST PG-B it creates:
--    Early Numeracy  > chapter "Play Quiz: Numbers & Shapes"  > 10 questions
--    Early Literacy  > chapter "Play Quiz: Letters & Sounds"  > 10 questions
--    quiz "Play Quiz 1: Numbers & Shapes"  (published, 10 marks, weightage 0)
--    quiz "Play Quiz 2: Letters & Sounds"  (published, 10 marks, weightage 0)
--  in the year "TEST 2026-27". Any TEST student enrolled in a PG section sees both.
-- =====================================================================

begin;

do $$
begin
  if (select count(*) from public.students where student_code not like 'TEST-%') > 50 then
    raise exception 'STOP: this database has real students. Run this only on the DEV project.';
  end if;
  if not exists (select 1 from public.academic_years where label = 'TEST 2026-27') then
    raise exception 'STOP: year "TEST 2026-27" is missing. Run scripts/seed/sql/seed-dev.sql first.';
  end if;
  if (select count(*) from public.subjects s join public.classes c on c.id = s.class_id
      where c.name in ('TEST PG-A', 'TEST PG-B')
        and s.name in ('Early Numeracy', 'Early Literacy')) <> 4 then
    raise exception 'STOP: TEST PG-A / TEST PG-B and their Early Numeracy + Early Literacy subjects are missing. Run scripts/seed/sql/seed-dev.sql first.';
  end if;
end $$;

-- The two quizzes (one chapter each, per section).
create temp table pgq_quiz (
  quiz        text primary key,
  subject     text not null,
  chapter     text not null,
  title       text not null,
  sort_order  int  not null
) on commit drop;

insert into pgq_quiz values
  ('num', 'Early Numeracy', 'Play Quiz: Numbers & Shapes', 'Play Quiz 1: Numbers & Shapes', 90),
  ('lit', 'Early Literacy', 'Play Quiz: Letters & Sounds', 'Play Quiz 2: Letters & Sounds', 90);

-- The 20 questions. body.seed is the idempotency key (unique per chapter).
create temp table pgq_item (
  seed     text primary key,
  quiz     text not null,
  pos      int  not null,
  type     text not null,
  cog      text not null,
  body     jsonb not null,
  answer   jsonb not null
) on commit drop;

