-- Sections to fill.
create temp table pgq_class on commit drop as
select c.id as class_id, c.name, y.id as year_id
from public.classes c
cross join public.academic_years y
where c.name in ('TEST PG-A', 'TEST PG-B') and y.label = 'TEST 2026-27';

-- 1. Chapters.
insert into public.chapters (subject_id, title, sort_order)
select s.id, q.chapter, q.sort_order
from pgq_class k
join public.subjects s on s.class_id = k.class_id
join pgq_quiz q on q.subject = s.name
where not exists (
  select 1 from public.chapters ch where ch.subject_id = s.id and ch.title = q.chapter);

-- 2. Questions (body gets its seed key).
insert into public.questions (chapter_id, type, cognitive_level, body, answer, default_marks)
select ch.id, i.type, i.cog, i.body || jsonb_build_object('seed', i.seed), i.answer, 1
from pgq_class k
join public.subjects s on s.class_id = k.class_id
join pgq_quiz q on q.subject = s.name
join public.chapters ch on ch.subject_id = s.id and ch.title = q.chapter
join pgq_item i on i.quiz = q.quiz
where not exists (
  select 1 from public.questions x where x.chapter_id = ch.id and x.body->>'seed' = i.seed)
order by k.name, q.quiz, i.pos;

-- 3. Quizzes, published straight away (weightage 0: no effect on report cards).
insert into public.assessments
  (year_id, class_id, subject_id, title, type, weightage, total_marks, scheduled_on, status)
select k.year_id, k.class_id, s.id, q.title, 'quiz', 0,
       (select count(*) from pgq_item i where i.quiz = q.quiz), current_date, 'published'
from pgq_class k
join public.subjects s on s.class_id = k.class_id
join pgq_quiz q on q.subject = s.name
where not exists (
  select 1 from public.assessments a
  where a.class_id = k.class_id and a.year_id = k.year_id and a.title = q.title);

-- 4. Put the questions in the quizzes, in order, 1 mark each.
insert into public.assessment_questions (assessment_id, question_id, marks, sort_order)
select a.id, x.id, 1, i.pos
from pgq_class k
join public.subjects s on s.class_id = k.class_id
join pgq_quiz q on q.subject = s.name
join public.assessments a on a.class_id = k.class_id and a.year_id = k.year_id and a.title = q.title
join public.chapters ch on ch.subject_id = s.id and ch.title = q.chapter
join pgq_item i on i.quiz = q.quiz
join public.questions x on x.chapter_id = ch.id and x.body->>'seed' = i.seed
on conflict (assessment_id, question_id) do nothing;

-- Check: expect 4 rows (2 sections x 2 quizzes), each "published | 10 | 10".
select c.name as class, a.title, a.status, a.total_marks,
       count(aq.question_id) as questions
from public.assessments a
join public.classes c on c.id = a.class_id
left join public.assessment_questions aq on aq.assessment_id = a.id
where c.name in ('TEST PG-A', 'TEST PG-B')
  and a.title in (select title from pgq_quiz)
group by c.name, a.title, a.status, a.total_marks
order by c.name, a.title;

commit;
